BEGIN READ ONLY;SET LOCAL statement_timeout='10s';SELECT jsonb_build_object('role',current_user,'db',current_database(),'readOnly',current_setting('transaction_read_only'),'ownerBypassesRls',(SELECT rolbypassrls FROM pg_roles WHERE rolname=current_user),'tables',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'force',c.relforcerowsecurity,'acl',c.relacl,'owner',pg_get_userbyid(c.relowner))),'[]'::jsonb) FROM pg_class c WHERE c.relnamespace='backend_core'::regnamespace AND c.relname IN('tzs_onboarding_rollout','tzs_onboarding_allowlist','tzs_onboarding_rollout_audit'))) metadata;ROLLBACK;